const items = $input.all();
const results = [];

for (const item of items) {
    const binaryData = item.binary?.data;

    if (!binaryData) continue;

    let fileSizeInBytes = binaryData.fileSize;

    // Converte a string (ex: "363 kB") para número absoluto de bytes
    if (typeof fileSizeInBytes === 'string') {
        const parts = fileSizeInBytes.split(' ');
        const valor = parseFloat(parts[0]);
        const unidade = parts[1]?.toLowerCase() || '';

        if (unidade.includes('m')) { // MB
            fileSizeInBytes = valor * 1024 * 1024;
        } else if (unidade.includes('k')) { // kB
            fileSizeInBytes = valor * 1024;
        } else {
            fileSizeInBytes = valor;
        }
    }

    /**
     * AJUSTE DE PRECISÃO:
     * Seu teste: 363 kB (~371.712 bytes) para 18 segundos.
     * Cálculo: 371712 / 18 = 20650 bytes por segundo.
     */
    const bytesPerSecond = 20650; 
    const durationSeconds = fileSizeInBytes / bytesPerSecond;

    results.push({
        json: {
            duration: new Date(durationSeconds * 1000).toISOString().substr(11, 8)
        }
    });
}

return results;

