// Acessa os dados do nó "busca_legenda"
const data = $node["busca_legenda"].json;

// Extrai apenas as frases do array 'transcript'
const frases = data.transcript.map(item => item.text);

// Junta todas as frases com um espaço entre elas
const textoCompleto = frases.join(' ');

// Opcional: Limpa espaços duplos ou quebras de linha indesejadas
const textoLimpo = textoCompleto.replace(/\n/g, ' ').replace(/\s+/g, ' ').trim();

return {
  texto_completo: textoLimpo
};

// 1. Captura a string de narração
const inputData = $input.first().json;
let texto = inputData.narracao || "";

if (!texto) {
    throw new Error("Campo 'narracao' não encontrado.");
}

// 2. TRATAMENTO DE CARACTERES: Limpa escapes de JSON e formatação poluída
// Remove aspas escapadas (\"), quebras de linha literais (\\n) e espaços duplos
texto = texto
    .replace(/\\"/g, '"')          // Transforma \" em "
    .replace(/\\n/g, ' ')          // Transforma \n em espaço
    .replace(/\s+/g, ' ')          // Remove espaços duplos ou tabs
    .trim();

const LIMITE_CARACTERES = 4000;
const blocos = [];

// 3. FUNÇÃO DE DIVISÃO INTELIGENTE
function dividirTexto(txt, limite) {
  let startIndex = 0;

  while (startIndex < txt.length) {
    let endIndex = startIndex + limite;

    if (endIndex < txt.length) {
      // Tenta cortar no último ponto final antes do limite para manter o sentido
      const lastPoint = txt.lastIndexOf('.', endIndex);
      const lastSpace = txt.lastIndexOf(' ', endIndex);

      if (lastPoint > startIndex + (limite * 0.8)) { 
        endIndex = lastPoint + 1; 
      } else if (lastSpace > startIndex) {
        endIndex = lastSpace;
      }
    }

    blocos.push({
      texto_parte: txt.substring(startIndex, endIndex).trim(),
      parte_numero: blocos.length + 1
    });

    startIndex = endIndex;
  }
}

dividirTexto(texto, LIMITE_CARACTERES);

// 4. Adiciona o total de partes para controle no n8n
const resultado = blocos.map(bloco => ({
  json: {
    ...bloco,
    total_partes: blocos.length,
    // Gera um nome de arquivo seguro
    file_name: `narracao_parte_${bloco.parte_numero}.mp3`
  }
}));

return resultado;

